// THE PUBLISHING GATE — the five rules, in one place.
//
// This sub-workflow is the ONLY code that decides whether something enters the
// archive. Scheduled ingestion, manual runs (M10) and any future backfill all
// call it, so the rules cannot drift between callers.
//
// The database enforces none of this. It stores what it is given and rejects
// only what is structurally impossible (a duplicate hash, a confidence outside
// 0..1). Every judgement below is n8n's.

const input = $('Called with a classified item').first().json;
const item = input.item;
const ai = input.ai;
const threshold = input.confidence_threshold;

const sourceRows = $('Re-read source').all().map(i => i.json).filter(r => r && r.id);
const hashRows = $('Look up hash').all().map(i => i.json).filter(r => r && r.id);

const reject = (reason, detail) => [{
  json: { published: false, reason, detail: detail ?? null, source_id: item.source_id, content_hash: item.content_hash },
}];

// ── Rule 0: the threshold itself must be present and sane ──────────────────
// ai.confidence_threshold is a FAIL-CLOSED setting. If it is missing or
// malformed the gate rejects everything rather than assuming a value, because
// assuming one could quietly widen what publishes.
if (typeof threshold !== 'number' || !Number.isFinite(threshold) || threshold < 0 || threshold > 1) {
  return reject('missing_confidence_threshold', String(threshold));
}

// ── Rule 1: the source is registered, active and verified ──────────────────
// Re-read at publish time, not trusted from the crawl: an admin may have
// deactivated or un-verified the source while this item was in flight.
const source = sourceRows[0];
if (!source) return reject('unknown_source');
if (!source.active) return reject('inactive_source', source.authority_ar);
if (source.config_status !== 'verified') return reject('unverified_source', source.config_status);

// ── Rule 2: the item's URL is on the source's allow-list ───────────────────
let host;
try {
  const u = new URL(item.source_url);
  if (u.protocol !== 'https:' && u.protocol !== 'http:') return reject('bad_url_scheme', u.protocol);
  host = u.hostname.toLowerCase();
} catch {
  return reject('malformed_url', item.source_url);
}
const allowed = (source.allowed_domains || []).map(d => String(d).toLowerCase());
if (!allowed.includes(host)) return reject('domain_mismatch', host);

// ── Rule 3: not already published ──────────────────────────────────────────
// The UNIQUE constraint is the backstop for the concurrent race; this is the
// ordinary path, and a duplicate is a skip, never an error.
if (hashRows.length > 0) return reject('duplicate', item.content_hash);

// ── Rule 4: confidence clears the threshold ────────────────────────────────
if (typeof ai.confidence !== 'number' || ai.confidence < threshold) {
  return reject('low_confidence', String(ai.confidence));
}

// ── Rule 5: it is actually a legal update ──────────────────────────────────
if (ai.is_legal_update !== true) return reject('not_legal_update');

// ── Publication date: taken, never invented ────────────────────────────────
// The crawler's date wins; the AI's is used only when the crawler found none.
// If neither exists the item is rejected rather than stamped with the fetch
// time, which would put a fabricated legal date in the archive.
const publicationDate = item.publication_date || ai.publication_date || null;
if (!publicationDate) return reject('no_publication_date');

// ── Country: the registry is authoritative ─────────────────────────────────
// The source's country is used unless the AI identified a GCC-wide instrument,
// which legitimately appears on national sites.
const country = ai.country === 'GCC' ? 'GCC' : source.country;

return [{
  json: {
    published: true,
    row: {
      source_id: source.id,
      content_hash: item.content_hash,
      source_url: item.source_url,
      title_ar: ai.title_ar,
      summary_ar: ai.summary_ar,
      country,
      category: ai.category,
      document_type: ai.document_type,
      legal_status: ai.legal_status,
      is_legal_update: true,
      confidence: ai.confidence,
      effective_date: ai.effective_date || null,
      publication_date: publicationDate,
      affected_entities: ai.affected_entities || [],
      keywords: ai.keywords || [],
      raw_excerpt: item.raw_excerpt,
      document_path: item.document_path || null,
      ai_model: item.ai_model,
    },
  },
}];

// Insert succeeded.
const row = $('Apply the five rules').first().json.row;
return [{ json: { outcome: 'published', source_id: row.source_id, content_hash: row.content_hash } }];

// Insert failed.
//
// A unique-violation here is the concurrent-execution race the constraint
// exists for: two runs classified the same item at once and both passed the
// gate's hash lookup. That is a DUPLICATE, not a failure — classifying it as
// an error would make a healthy source look broken.

const gate = $('Apply the five rules').first().json;
const err = $input.first().json.error ?? $input.first().json;
const message = String(err?.message ?? err?.details ?? err ?? 'insert failed');

const isDuplicate = /duplicate key|content_hash_unique|23505/i.test(message);

return [{
  json: {
    outcome: isDuplicate ? 'duplicate' : 'insert_failed',
    source_id: gate.row?.source_id ?? null,
    content_hash: gate.row?.content_hash ?? null,
    error_message: isDuplicate ? null : message.slice(0, 1000),
  },
}];

// Rejected by the gate. Not an error — a decision, carried back to the caller
// so it can be counted in workflow_logs.rejection_reasons.
const g = $input.first().json;
return [{ json: { outcome: 'rejected', reason: g.reason, detail: g.detail, source_id: g.source_id } }];
